ValidationRule.errorConditionFormula:
OR(
  /* 1. Scheme End Date before Scheme Start Date */
  AND(
    NOT(ISBLANK(Scheme_Start_Date__c)),
    NOT(ISBLANK(Scheme_End_Date__c)),
    Scheme_End_Date__c < Scheme_Start_Date__c
  ),

  /* 2. Second Stage End Date before Second Stage Start Date */
  AND(
    NOT(ISBLANK(Second_Stage_Start_Date__c)),
    NOT(ISBLANK(Second_Stage_End_Date__c)),
    Second_Stage_End_Date__c < Second_Stage_Start_Date__c
  ),

  /* 3. Second Stage Start Date before First Scheme End Date */
  AND(
    NOT(ISBLANK(Second_Stage_Start_Date__c)),
    NOT(ISBLANK(Scheme_End_Date__c)),
    Second_Stage_Start_Date__c < Scheme_End_Date__c
  )
)
